<?php require 'config.php'; $msg='';
if($_SERVER['REQUEST_METHOD']==='POST'){ $name=trim($_POST['name']??''); $contact=trim($_POST['contact']??''); $location=trim($_POST['location']??''); if($name!==''){ $s=$pdo->prepare('INSERT INTO farmers(name,contact,location) VALUES(?,?,?)'); $s->execute([$name,$contact,$location]); $msg='Farmer saved.'; }}
$list=$pdo->query('SELECT * FROM farmers ORDER BY farmer_id DESC')->fetchAll(); ?>
<!doctype html><html><head><meta charset="utf-8"><title>Farmers</title><link rel="stylesheet" href="style.css"></head><body><header><h1>Farmers</h1><nav><a href="index.php">Dashboard</a><a href="deliveries.php">Deliveries</a><a href="orders.php">Orders</a><a href="dispatches.php">Dispatches</a><a href="reports.php">Reports</a></nav></header><main><h2>Register Farmer</h2><?=htmlspecialchars($msg)?><form method="post"><label>Name<input name="name" required></label><label>Contact<input name="contact"></label><label>Location<input name="location"></label><button>Save Farmer</button></form><h2>Farmer Records</h2><table><tr><th>ID</th><th>Name</th><th>Contact</th><th>Location</th></tr><?php foreach($list as $f): ?><tr><td><?=$f['farmer_id']?></td><td><?=htmlspecialchars($f['name'])?></td><td><?=htmlspecialchars($f['contact'])?></td><td><?=htmlspecialchars($f['location'])?></td></tr><?php endforeach;?></table></main></body></html>
